 53→// --- Transcript Storage ---
 54→
 55→// ReadTranscript reads the transcript for a session.
 56→// The sessionRef is expected to be a path to the export JSON file.
 57→func (a *OpenCodeAgent) ReadTranscript(sessionRef string) ([]byte, error) {
 58→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path from agent hook
 59→	if err != nil {
 60→		return nil, fmt.Errorf("failed to read opencode transcript: %w", err)
 61→	}
 62→	return data, nil
 63→}
 64→
 65→// ChunkTranscript splits an OpenCode export JSON transcript by distributing messages across chunks.
 66→// OpenCode uses JSON format with {"info": {...}, "messages": [...]} structure.
 67→func (a *OpenCodeAgent) ChunkTranscript(content []byte, maxSize int) ([][]byte, error) {
 68→	var session ExportSession
 69→	if err := json.Unmarshal(content, &session); err != nil {
 70→		return nil, fmt.Errorf("failed to parse export session for chunking: %w", err)
 71→	}
 72→
 73→	if len(session.Messages) == 0 {
 74→		return [][]byte{content}, nil
 75→	}
 76→
 77→	// Marshal info to calculate accurate base size
 78→	infoBytes, err := json.Marshal(session.Info)
 79→	if err != nil {
 80→		return nil, fmt.Errorf("failed to marshal session info for chunking: %w", err)
 81→	}
 82→	// Base JSON structure size: {"info":<info>,"messages":[ ... ]}
 83→	baseSize := len(`{"info":`) + len(infoBytes) + len(`,"messages":[]}`)
 84→
 85→	var chunks [][]byte
 86→	var currentMessages []ExportMessage
 87→	currentSize := baseSize
 88→
 89→	for _, msg := range session.Messages {
 90→		// Marshal message to get its size
 91→		msgBytes, err := json.Marshal(msg)
 92→		if err != nil {
 93→			return nil, fmt.Errorf("failed to marshal message for chunking: %w", err)
 94→		}
 95→		msgSize := len(msgBytes) + 1 // +1 for comma separator
 96→
 97→		if currentSize+msgSize > maxSize && len(currentMessages) > 0 {
 98→			// Save current chunk
 99→			chunkData, err := json.Marshal(ExportSession{Info: session.Info, Messages: currentMessages})
100→			if err != nil {
101→				return nil, fmt.Errorf("failed to marshal chunk: %w", err)
102→			}
103→			chunks = append(chunks, chunkData)
104→
105→			// Start new chunk
106→			currentMessages = nil
107→			currentSize = baseSize
108→		}
109→
110→		currentMessages = append(currentMessages, msg)
111→		currentSize += msgSize
112→	}
113→
114→	// Add the last chunk
115→	if len(currentMessages) > 0 {
116→		chunkData, err := json.Marshal(ExportSession{Info: session.Info, Messages: currentMessages})
117→		if err != nil {
118→			return nil, fmt.Errorf("failed to marshal final chunk: %w", err)
119→		}
120→		chunks = append(chunks, chunkData)
121→	}
122→
123→	if len(chunks) == 0 {
124→		return nil, errors.New("failed to create any chunks")
125→	}
126→
127→	return chunks, nil
128→}
129→
130→// ReassembleTranscript merges OpenCode export JSON chunks by combining their message arrays.
131→func (a *OpenCodeAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
132→	if len(chunks) == 0 {
133→		return nil, errors.New("no chunks to reassemble")
134→	}
135→
136→	var allMessages []ExportMessage
137→	var sessionInfo SessionInfo
138→
139→	for i, chunk := range chunks {
140→		var session ExportSession
141→		if err := json.Unmarshal(chunk, &session); err != nil {
142→			return nil, fmt.Errorf("failed to unmarshal chunk %d: %w", i, err)
143→		}
144→		if i == 0 {
145→			sessionInfo = session.Info // Preserve session info from first chunk
146→		}
147→		allMessages = append(allMessages, session.Messages...)
148→	}
149→
150→	result, err := json.Marshal(ExportSession{Info: sessionInfo, Messages: allMessages})
151→	if err != nil {
152→		return nil, fmt.Errorf("failed to marshal reassembled transcript: %w", err)
153→	}
154→	return result, nil
155→}
