163→// GetSessionDir returns the directory where Entire stores OpenCode session transcripts.
164→// Transcripts are ephemeral handoff files between the TS plugin and the Go hook handler.
165→// Once checkpointed, the data lives on git refs and the file is disposable.
166→// Stored in os.TempDir()/entire-opencode/<sanitized-path>/ to avoid squatting on
167→// OpenCode's own directories (~/.opencode/ is project-level, not home-level).
168→func (a *OpenCodeAgent) GetSessionDir(repoPath string) (string, error) {
169→	// Check for test environment override
170→	if override := os.Getenv("ENTIRE_TEST_OPENCODE_PROJECT_DIR"); override != "" {
171→		return override, nil
172→	}
173→
174→	projectDir := SanitizePathForOpenCode(repoPath)
175→	return filepath.Join(os.TempDir(), "entire-opencode", projectDir), nil
176→}
