182→func (a *OpenCodeAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
183→	if input.SessionRef == "" {
184→		return nil, errors.New("no session ref provided")
185→	}
186→	data, err := os.ReadFile(input.SessionRef)
187→	if err != nil {
188→		return nil, fmt.Errorf("failed to read session: %w", err)
189→	}
190→
191→	// Parse to extract computed fields
192→	modifiedFiles, err := ExtractModifiedFiles(data)
193→	if err != nil {
194→		// Non-fatal: we can still return the session without modified files
195→		modifiedFiles = nil
196→	}
197→
198→	return &agent.AgentSession{
199→		AgentName:     a.Name(),
200→		SessionID:     input.SessionID,
201→		SessionRef:    input.SessionRef,
202→		NativeData:    data,
203→		ExportData:    data, // Export JSON is both native and export format
204→		ModifiedFiles: modifiedFiles,
205→	}, nil
206→}
207→
208→func (a *OpenCodeAgent) WriteSession(session *agent.AgentSession) error {
209→	if session == nil {
210→		return errors.New("nil session")
211→	}
212→	if session.SessionRef == "" {
213→		return errors.New("no session ref to write to")
214→	}
215→	if len(session.NativeData) == 0 {
216→		return errors.New("no session data to write")
217→	}
218→
219→	// 1. Write export JSON file (for Entire's internal checkpoint use)
220→	dir := filepath.Dir(session.SessionRef)
221→	//nolint:gosec // G301: Session directory needs standard permissions
222→	if err := os.MkdirAll(dir, 0o755); err != nil {
223→		return fmt.Errorf("failed to create session directory: %w", err)
224→	}
225→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
226→		return fmt.Errorf("failed to write session data: %w", err)
227→	}
228→
229→	// 2. If we have export data, import the session into OpenCode.
230→	//    This enables `opencode -s <id>` for both resume and rewind.
231→	if len(session.ExportData) == 0 {
232→		return nil // No export data — skip import (graceful degradation)
233→	}
234→
235→	if err := a.importSessionIntoOpenCode(session.SessionID, session.ExportData); err != nil {
236→		// Non-fatal: import is best-effort. The JSONL file is written,
237→		// and the user can always run `opencode import <file>` manually.
238→		fmt.Fprintf(os.Stderr, "warning: could not import session into OpenCode: %v\n", err)
239→	}
240→
241→	return nil
242→}
243→
244→// importSessionIntoOpenCode writes the export JSON to a temp file and runs
245→// `opencode import` to restore the session into OpenCode's database.
246→// For rewind (session already exists), the session is deleted first so the
247→// reimport replaces it with the checkpoint-state messages.
248→func (a *OpenCodeAgent) importSessionIntoOpenCode(sessionID string, exportData []byte) error {
249→	// Delete existing messages first so reimport replaces them cleanly.
250→	// opencode import uses ON CONFLICT DO NOTHING, so existing messages
251→	// would be skipped without this step (breaking rewind).
252→	// Uses direct SQLite delete since OpenCode CLI has no session delete command.
253→	if err := deleteMessagesFromSQLite(sessionID); err != nil {
254→		// Non-fatal: DB might not exist yet (first session), or sqlite3 not installed.
255→		// Import will still work for new sessions; only rewind of existing sessions
256→		// would have stale messages.
257→		fmt.Fprintf(os.Stderr, "warning: could not clear existing messages: %v\n", err)
258→	}
259→
260→	// Write export JSON to a temp file for opencode import
261→	tmpFile, err := os.CreateTemp("", "entire-opencode-export-*.json")
262→	if err != nil {
263→		return fmt.Errorf("failed to create temp file: %w", err)
264→	}
265→	defer os.Remove(tmpFile.Name())
266→
267→	if _, err := tmpFile.Write(exportData); err != nil {
268→		_ = tmpFile.Close()
269→		return fmt.Errorf("failed to write export data: %w", err)
270→	}
271→	if err := tmpFile.Close(); err != nil {
272→		return fmt.Errorf("failed to close temp file: %w", err)
273→	}
274→
275→	return runOpenCodeImport(tmpFile.Name())
276→}
