278→func (a *OpenCodeAgent) FormatResumeCommand(sessionID string) string {
279→	if strings.TrimSpace(sessionID) == "" {
280→		return "opencode"
281→	}
282→	return "opencode -s " + sessionID
283→}
284→
285→// nonAlphanumericRegex matches any non-alphanumeric character.
286→var nonAlphanumericRegex = regexp.MustCompile(`[^a-zA-Z0-9]`)
287→
288→// SanitizePathForOpenCode converts a path to a safe directory name.
289→// Replaces any non-alphanumeric character with a dash (same approach as Claude/Gemini).
290→func SanitizePathForOpenCode(path string) string {
291→	return nonAlphanumericRegex.ReplaceAllString(path, "-")
292→}
