  1→package opencode
  2→
  3→import (
  4→	"encoding/json"
  5→	"fmt"
  6→	"os"
  7→	"slices"
  8→	"strings"
  9→
 10→	"github.com/entireio/cli/cmd/entire/cli/agent"
 11→)
