321→// extractToolDetail extracts an appropriate detail string for a tool call.
322→// For tools in minimalDetailTools, only essential identifiers are shown.
323→// For other tools, the full detail chain is used.
324→func extractToolDetail(toolName string, input transcript.ToolInput) string {
325→	// For minimal detail tools, extract only the essential identifier
326→	if minimalDetailTools[toolName] {
327→		switch toolName {
328→		case "Skill":
329→			return input.Skill
330→		case "Read":
331→			if input.FilePath != "" {
332→				return input.FilePath
333→			}
334→			return input.NotebookPath
335→		case "WebFetch":
336→			return input.URL
337→		}
338→	}
339→
340→	// For other tools, use the full detail chain
341→	if input.Description != "" {
342→		return input.Description
343→	}
344→	if input.Command != "" {
345→		return input.Command
346→	}
347→	if input.FilePath != "" {
348→		return input.FilePath
349→	}
350→	if input.NotebookPath != "" {
351→		return input.NotebookPath
352→	}
353→	return input.Pattern
354→}
