 15→func newCleanCmd() *cobra.Command {
 16→	var forceFlag bool
 17→
 18→	cmd := &cobra.Command{
 19→		Use:   "clean",
 20→		Short: "Clean up orphaned Entire data",
 21→		Long: `Remove orphaned Entire data (session state, shadow branches, checkpoint metadata, temp files) that wasn't cleaned up automatically.
 22→
 23→This command finds and removes orphaned data from any strategy:
 24→
 25→  Shadow branches (entire/<commit-hash>)
 26→    Created by manual-commit strategy. Normally auto-cleaned when sessions
 27→    are condensed during commits.
 28→
 29→  Session state files (.git/entire-sessions/)
 30→    Track active sessions. Orphaned when no checkpoints or shadow branches
 31→    reference them.
 32→
 33→  Checkpoint metadata (entire/checkpoints/v1 branch)
 34→    For auto-commit checkpoints: orphaned when commits are rebased/squashed
 35→    and no commit references the checkpoint ID anymore.
 36→    Manual-commit checkpoints are permanent (condensed history) and are
 37→    never considered orphaned.
 38→
 39→  Temporary files (.entire/tmp/)
 40→    Cached transcripts and other temporary data. Safe to delete when no
 41→    active sessions are using them.
 42→
 43→Default: shows a preview of items that would be deleted.
 44→With --force, actually deletes the orphaned items.
 45→
 46→The entire/checkpoints/v1 branch itself is never deleted.`,
 47→		RunE: func(cmd *cobra.Command, _ []string) error {
 48→			return runClean(cmd.OutOrStdout(), forceFlag)
 49→		},
 50→	}
 51→
 52→	cmd.Flags().BoolVarP(&forceFlag, "force", "f", false, "Actually delete items (default: dry run)")
 53→
 54→	return cmd
 55→}
