 57→func runClean(w io.Writer, force bool) error {
 58→	// Initialize logging so structured logs go to .entire/logs/ instead of stderr.
 59→	// Error is non-fatal: if logging init fails, logs go to stderr (acceptable fallback).
 60→	logging.SetLogLevelGetter(GetLogLevel)
 61→	if err := logging.Init(""); err == nil {
 62→		defer logging.Close()
 63→	}
 64→
 65→	// List all cleanup items
 66→	items, err := strategy.ListAllCleanupItems()
 67→	if err != nil {
 68→		return fmt.Errorf("failed to list orphaned items: %w", err)
 69→	}
 70→
 71→	// List temp files
 72→	tempFiles, err := listTempFiles()
 73→	if err != nil {
 74→		// Non-fatal: continue with other cleanup items
 75→		fmt.Fprintf(w, "Warning: failed to list temp files: %v\n", err)
 76→	}
 77→
 78→	return runCleanWithItems(w, force, items, tempFiles)
 79→}
