 81→// listTempFiles returns all files in .entire/tmp/.
 82→func listTempFiles() ([]string, error) {
 83→	tmpDir, err := paths.AbsPath(paths.EntireTmpDir)
 84→	if err != nil {
 85→		return nil, fmt.Errorf("failed to get temp dir path: %w", err)
 86→	}
 87→
 88→	entries, err := os.ReadDir(tmpDir)
 89→	if os.IsNotExist(err) {
 90→		return nil, nil
 91→	}
 92→	if err != nil {
 93→		return nil, fmt.Errorf("failed to read temp dir: %w", err)
 94→	}
 95→
 96→	var files []string
 97→	for _, entry := range entries {
