105→// TempFileDeleteError contains a file name and the error that occurred during deletion.
106→type TempFileDeleteError struct {
107→	File string
108→	Err  error
109→}
110→
111→// deleteTempFiles removes all files in .entire/tmp/.
112→// Returns successfully deleted files and any failures with their error reasons.
113→func deleteTempFiles(files []string) (deleted []string, failed []TempFileDeleteError) {
114→	tmpDir, err := paths.AbsPath(paths.EntireTmpDir)
115→	if err != nil {
116→		// Can't get path - mark all as failed with the same error
117→		for _, file := range files {
118→			failed = append(failed, TempFileDeleteError{File: file, Err: err})
119→		}
120→		return nil, failed
121→	}
122→
123→	for _, file := range files {
124→		path := filepath.Join(tmpDir, file)
125→		if err := os.Remove(path); err != nil {
126→			failed = append(failed, TempFileDeleteError{File: file, Err: err})
127→		} else {
128→			deleted = append(deleted, file)
129→		}
130→	}
131→	return deleted, failed
132→}
